   156  class Object {
   157  public:
   158    Object() : type(objNone) {}
   159    ~Object() { free(); }
   160
   161    explicit Object(bool boolnA)
   162      { type = objBool; booln = boolnA; }
   163    explicit Object(int intgA)
   164      { type = objInt; intg = intgA; }
   165    explicit Object(ObjType typeA)
   166      { type = typeA; }
   167    explicit Object(double realA)
   168      { type = objReal; real = realA; }
   169    explicit Object(GooString *stringA)
   170      { assert(stringA); type = objString; string = stringA; }
   171    Object(ObjType typeA, const char *stringA)
   172      { assert(typeA == objName || typeA == objCmd); assert(stringA); type = typeA; cString = copyString(stringA); }
   173    explicit Object(long long int64gA)
   174      { type = objInt64; int64g = int64gA; }
   175    explicit Object(Array *arrayA)
   176      { assert(arrayA); type = objArray; array = arrayA; }
   177    explicit Object(Dict *dictA)
   178      { assert(dictA); type = objDict; dict = dictA; }
   179    explicit Object(Stream *streamA)
   180      { assert(streamA); type = objStream; stream = streamA; }
   181    explicit Object(const Ref r)
   182      { type = objRef; ref = r; }
   183
   184    template<typename T> Object(T) = delete;
   185
   186    Object(Object&& other) noexcept
   187    {
   188      std::memcpy(reinterpret_cast<void*>(this), &other, sizeof(Object));
   189      other.type = objDead;
   190    }
   191
   192    Object& operator=(Object&& other) noexcept
   193    {
   194      free();
   195
   196      std::memcpy(reinterpret_cast<void*>(this), &other, sizeof(Object));
   197      other.type = objDead;
   198
   199      return *this;
   200    }
   201
   202    Object &operator=(const Object &other) = delete;
   203    Object(const Object &other) = delete;
   204
   205    // Set object to null.
   206    void setToNull() { free(); type = objNull; }
   207
   208    // Copy this to obj
   209    Object copy() const;
   210
   211    // If object is a Ref, fetch and return the referenced object.
   212    // Otherwise, return a copy of the object.
   213    Object fetch(XRef *xref, int recursion = 0) const;
