   215    // Type checking.
   216    ObjType getType() const { CHECK_NOT_DEAD; return type; }
   217    bool isBool() const { CHECK_NOT_DEAD; return type == objBool; }
   218    bool isInt() const { CHECK_NOT_DEAD; return type == objInt; }
   219    bool isReal() const { CHECK_NOT_DEAD; return type == objReal; }
   220    bool isNum() const { CHECK_NOT_DEAD; return type == objInt || type == objReal || type == objInt64; }
