   222    bool isName() const { CHECK_NOT_DEAD; return type == objName; }
   223    bool isNull() const { CHECK_NOT_DEAD; return type == objNull; }
   224    bool isArray() const { CHECK_NOT_DEAD; return type == objArray; }
   225    bool isDict() const { CHECK_NOT_DEAD; return type == objDict; }
   226    bool isStream() const { CHECK_NOT_DEAD; return type == objStream; }
   227    bool isRef() const { CHECK_NOT_DEAD; return type == objRef; }
   228    bool isCmd() const { CHECK_NOT_DEAD; return type == objCmd; }
   229    bool isError() const { CHECK_NOT_DEAD; return type == objError; }
   230    bool isEOF() const { CHECK_NOT_DEAD; return type == objEOF; }
   231    bool isNone() const { CHECK_NOT_DEAD; return type == objNone; }
   232    bool isInt64() const { CHECK_NOT_DEAD; return type == objInt64; }
   233    bool isIntOrInt64() const { CHECK_NOT_DEAD; return type == objInt || type == objInt64; }
   234
   235    // Special type checking.
   236    bool isName(const char *nameA) const
   237      { return type == objName && !strcmp(cString, nameA); }
   238    bool isDict(const char *dictType) const;
   239    bool isCmd(const char *cmdA) const
   240      { return type == objCmd && !strcmp(cString, cmdA); }
   241
   242    // Accessors.
   243    bool getBool() const { OBJECT_TYPE_CHECK(objBool); return booln; }
   244    int getInt() const { OBJECT_TYPE_CHECK(objInt); return intg; }
   245    double getReal() const { OBJECT_TYPE_CHECK(objReal); return real; }
   246
   247    // Note: integers larger than 2^53 can not be exactly represented by a double.
   248    // Where the exact value of integers up to 2^63 is required, use isInt64()/getInt64().
   249    double getNum() const { OBJECT_3TYPES_CHECK(objInt, objInt64, objReal);
   250      return type == objInt ? (double)intg : type == objInt64 ? (double)int64g : real; }
   251    double getNum(bool *ok) const {
   252      if (unlikely(type != objInt && type != objInt64 && type != objReal)) {
