   255      }
   256      return type == objInt ? (double)intg : type == objInt64 ? (double)int64g : real;
   257    }
   258    const GooString *getString() const { OBJECT_TYPE_CHECK(objString); return string; }
   259    // After takeString() the only method that should be called for the object is free().
   260    GooString *takeString() { OBJECT_TYPE_CHECK(objString); type = objDead; return string; }
   261    const char *getName() const { OBJECT_TYPE_CHECK(objName); return cString; }
   262    Array *getArray() const { OBJECT_TYPE_CHECK(objArray); return array; }
   263    Dict *getDict() const { OBJECT_TYPE_CHECK(objDict); return dict; }
