   269    long long getInt64() const { OBJECT_TYPE_CHECK(objInt64); return int64g; }
   270    long long getIntOrInt64() const { OBJECT_2TYPES_CHECK(objInt, objInt64);
   271      return type == objInt ? intg : int64g; }
   272
   273    // Array accessors.
   274    int arrayGetLength() const;
   275    void arrayAdd(Object &&elem);
   276    void arrayRemove(int i);
   277    Object arrayGet(int i, int recursion) const;
   278    const Object &arrayGetNF(int i) const;
