   280    // Dict accessors.
   281    int dictGetLength() const;
   282    void dictAdd(char *key, Object &&val) = delete;
   283    void dictAdd(const char *key, Object &&val);
   284    void dictSet(const char *key, Object &&val);
   285    void dictRemove(const char *key);
   286    bool dictIs(const char *dictType) const;
   287    Object dictLookup(const char *key, int recursion = 0) const;
   288    const Object &dictLookupNF(const char *key) const;
   289    const char *dictGetKey(int i) const;
   290    Object dictGetVal(int i) const;
   291    const Object &dictGetValNF(int i) const;
   292
   293    // Stream accessors.
   294    void streamReset();
   295    void streamClose();
   296    int streamGetChar() const;
   297    int streamGetChars(int nChars, unsigned char *buffer) const;
   298    void streamSetPos(Goffset pos, int dir = 0);
   299    Dict *streamGetDict() const;
   300
   301    // Output.
   302    const char *getTypeName() const;
   303    void print(FILE *f = stdout) const;
   304
   305    double getNumWithDefaultValue(double defaultValue) const {
   306      if (unlikely(type != objInt && type != objInt64 && type != objReal)) {
   307        return defaultValue;
   308      }
   309      return type == objInt ? (double)intg : type == objInt64 ? (double)int64g : real;
   310    }
   311
   312    bool getBoolWithDefaultValue(bool defaultValue) const {
   313      return (type == objBool) ? booln : defaultValue;
   314    }
