   316  private:
   317    // Free object contents.
   318    void free();
   319
   320    ObjType type;                 // object type
   321    union {                       // value for each type:
   322      bool booln;         //   boolean
   323      int intg;                   //   integer
   324      long long int64g;           //   64-bit integer
   325      double real;                //   real
   326      GooString *string;          //   string
   327      char *cString;              //   name or command, depending on objType
