   362  /* Loads standalone fields into Page, should be called once per page only */
   363  void Page::loadStandaloneFields(Annots *annotations, Form *form) {
   364    const int numAnnots = annotations ? annotations->getNumAnnots() : 0;
   365    if (numAnnots < 1)
   366      return;
   367
   368    /* Look for standalone annots, identified by being: 1) of type Widget
   369     * 2) of subtype Button 3) not referenced from the Catalog's Form Field array */
   370    for (int i = 0; i < numAnnots; ++i) {
   371      Annot *annot = annotations->getAnnot(i);
   372
   373      if (annot->getType() != Annot::typeWidget || !annot->getHasRef())
   374        continue;
   375
   376      const Ref r = annot->getRef();
   377      if (form && form->findWidgetByRef(r))
   378        continue; // this annot is referenced inside Form, skip it
   379
   380      std::set<int> parents;
   381      FormField *field = Form::createFieldFromDict (Object(annot->getDict()),
   382                                                    annot->getDoc(), r, nullptr, &parents);
   383
   384      if (field && field->getType() == formButton && field->getNumWidgets() == 1) {
   385
   386        field->setStandAlone(true);
   387        FormWidget *formWidget = field->getWidget(0);
   388
   389        if (!formWidget->getWidgetAnnotation())
   390          formWidget->createWidgetAnnotation();
   391
   392        standaloneFields.push_back(field);
   393
   394      } else if (field) {
   395        delete field;
   396      }
   397    }
   398  }
