   631  FormField::FormField(PDFDoc *docA, Object &&aobj, const Ref aref, FormField *parentA, std::set<int> *usedParents, FormFieldType ty)
   632  {
   633    doc = docA;
   634    xref = doc->getXRef();
   635    obj = std::move(aobj);
   636    Dict* dict = obj.getDict();
   637    ref = aref;
   638    type = ty;
   639    parent = parentA;
   640    numChildren = 0;
   641    children = nullptr;
   642    terminal = false;
   643    widgets = nullptr;
   644    readOnly = false;
   645    defaultAppearance = nullptr;
   646    fullyQualifiedName = nullptr;
   647    quadding = quaddingLeftJustified;
   648    hasQuadding = false;
   649    standAlone = false;
   650
   651    //childs
   652    Object obj1 = dict->lookup("Kids");
   653    if (obj1.isArray()) {
   654      // Load children
   655      for (int i = 0 ; i < obj1.arrayGetLength(); i++) {
   656        Ref childRef;
   657        Object childObj = obj1.getArray()->get(i, &childRef);
   658        if (childRef == Ref::INVALID()) {
   659          error (errSyntaxError, -1, "Invalid form field renference");
   660          continue;
   661        }
   662        if (!childObj.isDict()) {
   663          error (errSyntaxError, -1, "Form field child is not a dictionary");
   664          continue;
   665        }
   666
   667        if (usedParents->find(childRef.num) == usedParents->end()) {
   668          // Field child: it could be a form field or a widget or composed dict
   669          const Object &objParent = childObj.dictLookupNF("Parent");
   670          Object obj3 = childObj.dictLookup("Parent");
   671          if (objParent.isRef() || obj3.isDict()) {
   672            // Child is a form field or composed dict
   673            // We create the field, if it's composed
   674            // it will create the widget as a child
   675            std::set<int> usedParentsAux = *usedParents;
   676            usedParentsAux.insert(childRef.num);
   677
   678            if (terminal) {
   679              error(errSyntaxWarning, -1, "Field can't have both Widget AND Field as kids\n");
   680              continue;
   681            }
   682
   683            numChildren++;
   684            children = (FormField**)greallocn(children, numChildren, sizeof(FormField*));
   685            children[numChildren - 1] = Form::createFieldFromDict(std::move(childObj), doc, childRef, this, &usedParentsAux);
   686          } else {
   687            Object obj2 = childObj.dictLookup("Subtype");
   688            if (obj2.isName("Widget")) {
   689              // Child is a widget annotation
   690              if (!terminal && numChildren > 0) {
   691                error(errSyntaxWarning, -1, "Field can't have both Widget AND Field as kids\n");
   692                continue;
   693              }
   694              _createWidget(&childObj, childRef);
   695            }
   696          }
   697        }
   698      }
   699    } else {
   700      // No children, if it's a composed dict, create the child widget
   701      obj1 = dict->lookup("Subtype");
   702      if (obj1.isName("Widget"))
   703        _createWidget(&obj, ref);
   704    }
   705
   706    //flags
   707    obj1 = Form::fieldLookup(dict, "Ff");
   708    if (obj1.isInt()) {
   709      int flags = obj1.getInt();
   710      if (flags & 0x1) { // 1 -> ReadOnly
   711        readOnly = true;
   712      }
   713      if (flags & 0x2) { // 2 -> Required
   714        //TODO
   715      }
   716      if (flags & 0x4) { // 3 -> NoExport
   717        //TODO
   718      }
   719    }
   720
   721    // Variable Text
   722    obj1 = Form::fieldLookup(dict, "DA");
   723    if (obj1.isString())
   724      defaultAppearance = obj1.getString()->copy();
   725
   726    obj1 = Form::fieldLookup(dict, "Q");
   727    if (obj1.isInt()) {
   728      quadding = static_cast<VariableTextQuadding>(obj1.getInt());
   729      hasQuadding = true;
   730    }
   731
   732    obj1 = dict->lookup("T");
   733    if (obj1.isString()) {
   734      partialName = obj1.getString()->copy();
   735    } else {
   736      partialName = nullptr;
   737    }
   738
   739    obj1 = dict->lookup("TU");
   740    if (obj1.isString()) {
   741      alternateUiName = obj1.getString()->copy();
   742    } else {
   743      alternateUiName = nullptr;
   744    }
   745
   746    obj1 = dict->lookup("TM");
   747    if(obj1.isString()) {
   748      mappingName = obj1.getString()->copy();
   749    } else {
   750      mappingName = nullptr;
   751    }
   752  }
